// 环境变量必须在 config 求值前加载：ESM 的 import 会提升，所以放在 body 顶部调用
import fs from 'node:fs';
import path from 'node:path';

import { loadEnv } from './utils/env-loader';
import { defineConfig, devices } from '@playwright/test';

loadEnv();
{{#if authState}}/** 账号配了才挂对应登录态；没配就匿名跑，不去读一个不存在的 .auth 文件 */
const hasAccount = (user?: string, pass?: string) =>
  Boolean((user ?? '').trim() && (pass ?? '').trim());
const adminReady = hasAccount(process.env.ADMIN_USERNAME, process.env.ADMIN_PASSWORD);
const userReady = hasAccount(process.env.USER_USERNAME, process.env.USER_PASSWORD);
/** 一个账号都没配就不挂 setup：既少一次空跑，也不会在报告里留两条 skip */
const authReady = adminReady || userReady;
{{/if}}
/**
 * 框架自检用例：只在还没有业务用例时参与运行。
 * tests/ 下出现别的 .spec.ts 就自动排除（不跑、也不进报告）；
 * 需要再确认框架连通性时跑 `pnpm run check:framework`（那条用环境变量强制打开）。
 */
const SELF_CHECK = 'tests/smoke/framework.spec.ts';
function listSpecs(dir: string): string[] {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return [];
  }
  return entries.flatMap((entry) => {
    const abs = path.join(dir, entry.name);
    if (entry.isDirectory()) return listSpecs(abs);
    if (!entry.name.endsWith('.spec.ts')) return [];
    return [path.relative(process.cwd(), abs).replace(/\\/g, '/')];
  });
}
const hasBusinessSpecs = listSpecs(path.join(process.cwd(), 'tests')).some(
  (file) => file !== SELF_CHECK,
);
const frameworkCheck = process.env.FORCE_FRAMEWORK_CHECK === '1' || !hasBusinessSpecs;
/**
 * 企业级基础配置：
 * - 环境由 ENV 选择（test / prod），变量来自 .env.<ENV>，仓库里不写真实口令；
 * - 不按文件名分流 testMatch，否则后续写进 tests/ 根目录的用例会静默不执行；
 * - retries / workers / forbidOnly 在 CI 与本地是两套策略；
 * - 配了账号时 chromium 默认用管理员身份，打了 @user 的用例跑在 chromium-user 上。
 */
{{#if webServer}}/** 自启动命令：多数项目测的是已部署的远端服务，没配就一律不自启动，安静连 BASE_URL */
const webServerCommand = (process.env.WEB_SERVER_COMMAND ?? '').trim();
/** 自启动只服务本机地址：BASE_URL 指向远端时不能再拿它当探活目标，否则本地服务永远不会被拉起 */
const webServerUrl = (process.env.WEB_SERVER_URL || '{{baseURL}}').trim();
/** 探活地址落在本机时才提示「没配启动命令」；远端服务属于正常情况，不打扰 */
function isLocalUrl(raw: string): boolean {
  try {
    return ['localhost', '127.0.0.1', '0.0.0.0', '[::1]'].includes(new URL(raw).hostname);
  } catch {
    return false;
  }
}
if (!webServerCommand && isLocalUrl(webServerUrl)) {
  console.warn(
    '[webServer] 探活地址是本机 ' + webServerUrl + '，但没配 WEB_SERVER_COMMAND：只会连已启动的服务，不会自动拉起',
  );
}
{{/if}}
export default defineConfig({
  testDir: './tests',
  testMatch: '**/*.spec.ts',
  // 有业务用例后自检不参与任何一次运行（不跑、也不进报告）
  testIgnore: frameworkCheck ? [] : ['**/framework.spec.ts'],
  timeout: 30_000,
  expect: { timeout: 10_000 },
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 2 : undefined,
  fullyParallel: true,
  forbidOnly: Boolean(process.env.CI),
  // CI 分片：每个分片只出 blob，最后由 merge-reports 合成一份 HTML
  reporter: process.env.CI
    ? [
        // 分片报告：最后用 merge-reports 合成一份 HTML
        ['blob', { outputDir: 'reports/blob' }],
        ['github'],{{#if allure}}
        // 注意：allure-playwright 用 resultsDir，写成 outputFolder 会静默落到根目录
        ['allure-playwright', { resultsDir: 'reports/allure-results' }],{{/if}}
      ]
    : [
        // 本地直出 HTML，跑完不自动打开
        ['list'],
        ['html', { outputFolder: 'reports/playwright-report', open: 'never' }],{{#if allure}}
        ['allure-playwright', { resultsDir: 'reports/allure-results' }],{{/if}}
      ],
  use: {
    baseURL: process.env.BASE_URL || '{{baseURL}}',
    actionTimeout: 15_000,
    screenshot: 'only-on-failure',
    trace: 'retain-on-failure',
    video: 'retain-on-failure',
    locale: 'zh-CN',
  },
{{#if webServer}}
  // 本地没起被测系统时由 Playwright 拉起；CI 里打的是已部署环境，
  // 不能再执行启动命令，否则流水线会去启动一个根本不存在的服务
  ...(process.env.CI || !webServerCommand
    ? {}
    : {
        webServer: {
          command: webServerCommand,
          // 与 BASE_URL 解耦：探活只针对本机地址
          url: webServerUrl,
          reuseExistingServer: true,
          timeout: 120_000,
          stderr: 'pipe' as const,
        },
      }),
{{/if}}
  projects: [{{#if authState}}
    // 先登录一次并写 .auth/admin.json、.auth/user.json；没配账号就整块不挂
    ...(authReady ? [{ name: 'setup', testMatch: /.*\.setup\.ts/ }] : []),
{{/if}}
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],{{#if authState}}
        // 管理员登录态作为默认身份；登录类用例用 test.use 自己清空
        ...(adminReady ? { storageState: '.auth/admin.json' } : {}),{{/if}}
      },{{#if authState}}
      // 普通用户身份的用例交给下面的 chromium-user，避免同一用例跑两遍
      ...(authReady ? { dependencies: ['setup'], grepInvert: /@user/ } : {}),{{/if}}
    },{{#if authState}}
    // 只在配了 USER 账号时出现：打 @user 的用例用它跑
    ...(userReady
      ? [
          {
            name: 'chromium-user',
            use: { ...devices['Desktop Chrome'], storageState: '.auth/user.json' },
            dependencies: ['setup'],
            grep: /@user/,
          },
        ]
      : []),{{/if}}
  ],
});

import { expect, type Locator, type Page } from '@playwright/test';

/**
 * 页面对象基类：统一导航、就绪等待与常见断言。
 * 新增页面继承它即可，不用每处重复写等待逻辑。
 */
export class BasePage {
  constructor(protected readonly page: Page) {}

  /** 以 baseURL 为基准打开页面，并等首屏加载完成 */
  async navigate(path = '/'): Promise<void> {
    await this.page.goto(path);
    // 不用 networkidle：有长轮询 / WebSocket 的页面会一直等不到，直接超时
    await this.page.waitForLoadState('load');
  }

  /** 等表格 loading 消失且第一行出现（Ant Design 列表页通用） */
  async waitForTableLoaded(): Promise<void> {
    await this.page
      .locator('.ant-spin-spinning')
      .first()
      .waitFor({ state: 'hidden' })
      .catch(() => {});
    await this.page
      .locator('.ant-table-row')
      .first()
      .waitFor({ state: 'visible' })
      .catch(() => {});
  }

  toast(text: string | RegExp): Locator {
    return this.page.getByText(text).first();
  }

  async expectToast(text: string | RegExp): Promise<void> {
    await expect(this.toast(text)).toBeVisible();
  }

  async expectUrl(pattern: string | RegExp): Promise<void> {
    await expect(this.page).toHaveURL(pattern);
  }
}

import type { Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';
import { requireEnv } from '../utils/config';

/**
 * 登录页示例：选择器按实际系统改，账号从环境变量读，不落仓库。
 * 有验证码 / 单点登录时改成手动登录并保存 storageState（见 tests/auth.setup.ts）。
 */
export class LoginPage extends BasePage {
  readonly username: Locator;
  readonly password: Locator;
  readonly submit: Locator;

  constructor(page: Page) {
    super(page);
    // testid 优先，退化到唯一 label。真出现多命中要补 testid，而不是靠 first 长期掩盖。
    this.username = page
      .getByTestId('login-username')
      .or(page.getByLabel(/^(用户名|账号|手机号)$/))
      .first();
    this.password = page
      .getByTestId('login-password')
      .or(page.getByLabel(/^密码$/))
      .first();
    this.submit = page
      .getByTestId('login-submit')
      .or(page.getByRole('button', { name: /^登\s*录$/ }))
      .first();
  }

  async open(path = '/login'): Promise<void> {
    await this.navigate(path);
  }

  async login(
    user = requireEnv('ADMIN_USERNAME'),
    pass = requireEnv('ADMIN_PASSWORD'),
  ): Promise<void> {
    await this.username.fill(user);
    await this.password.fill(pass);
    await this.submit.click();
    await this.page.waitForLoadState('load');
  }
}

import { loadEnv } from './env-loader';

// 自定义 runner / 独立脚本也会 import 这里：先加载 .env，重复调用无副作用
loadEnv();

/** 环境变量读取：关键变量缺失时尽早失败，避免用例跑一半才报错 */
export function readEnv(name: string, fallback = ''): string {
  const value = (process.env[name] ?? '').trim();
  return value || fallback;
}

export function requireEnv(name: string): string {
  const value = readEnv(name);
  if (!value) {
    throw new Error(`缺少环境变量 ${name}，请复制 .env.example 为 .env.<ENV> 并填写`);
  }
  return value;
}

export type Role = 'admin' | 'user';

/**
 * 用 getter 而不是模块级常量：模块被导入的时机不确定（独立脚本 / 自定义 runner），
 * 常量会把「.env 还没加载」时的空值固化下来，之后怎么改环境变量都读不到。
 */
export const config = {
  get baseUrl(): string {
    // 兜底与 playwright.config.ts 的 baseURL 保持一致，避免两处地址不同导致排查误判
    return readEnv('BASE_URL', '{{baseURL}}');
  },
  get admin(): { username: string; password: string } {
    return { username: readEnv('ADMIN_USERNAME'), password: readEnv('ADMIN_PASSWORD') };
  },
  get user(): { username: string; password: string } {
    return { username: readEnv('USER_USERNAME'), password: readEnv('USER_PASSWORD') };
  },
};

/** 账号没配时用例应 skip，而不是报错 */
export function hasAccount(role: Role): boolean {
  const item = config[role];
  return Boolean(item.username && item.password);
}

import fs from 'node:fs';
import path from 'node:path';
import dotenv from 'dotenv';

/** 当前环境：test / prod；缺省 test */
export const ENV_NAME = (process.env.ENV || 'test').trim().toLowerCase();

/** 本机回环地址：prod 打到这里一定是配错了（.env 不随仓库分发时最容易踩） */
const LOOPBACK = /^(https?:\/\/)?(localhost|127\.0\.0\.1|0\.0\.0\.0|\[::1\])(:|\/|$)/i;

/**
 * 按 ENV 加载变量：先 .env.<ENV>，再 .env 补缺（后者不覆盖前者）。
 * 必须在 playwright.config.ts 的 body 顶部调用一次。
 */
export function loadEnv(cwd = process.cwd()): void {
  for (const name of [`.env.${ENV_NAME}`, '.env']) {
    const abs = path.join(cwd, name);
    if (!fs.existsSync(abs)) continue;
    // override: false —— .env 只当共用默认值，不覆盖具体环境
    dotenv.config({ path: abs, override: false });
  }

  // 生产保护：prod 必须显式开 ALLOW_PROD，且自己写 BASE_URL
  if (ENV_NAME === 'prod') {
    if (process.env.ALLOW_PROD !== 'true') {
      throw new Error('拒绝在 prod 环境运行：确认目标后设置 ALLOW_PROD=true 再试');
    }
    // .env 被 .gitignore 忽略、不随仓库分发：少了 BASE_URL 会悄悄落到 config 的兜底地址，
    // 看着跑完了其实打的是本机，所以这里必须直接拒绝
    const baseUrl = (process.env.BASE_URL ?? '').trim();
    if (!baseUrl) {
      throw new Error('拒绝在 prod 环境运行：.env.prod 里必须显式设置 BASE_URL');
    }
    if (LOOPBACK.test(baseUrl)) {
      throw new Error(`拒绝在 prod 环境运行：BASE_URL 指向本机地址（${baseUrl}），请改成生产域名`);
    }
  }
  if (!process.env.BASE_URL) {
    console.warn(`[env] ENV=${ENV_NAME} 但没有 BASE_URL，用例会用到 config 里的兜底地址`);
  }
}

type LogLevel = 'DEBUG' | 'INFO' | 'WARN' | 'ERROR';

const LEVEL_RANK: Record<LogLevel, number> = { DEBUG: 0, INFO: 1, WARN: 2, ERROR: 3 };

/** 轻量日志：带时间戳与级别，比 console.log 更容易看执行时序 */
class Logger {
  private level: LogLevel = 'DEBUG';

  setLevel(level: LogLevel): void {
    this.level = level;
  }

  debug(msg: string, ...args: unknown[]): void {
    this.write('DEBUG', msg, args);
  }

  info(msg: string, ...args: unknown[]): void {
    this.write('INFO', msg, args);
  }

  warn(msg: string, ...args: unknown[]): void {
    this.write('WARN', msg, args);
  }

  error(msg: string, ...args: unknown[]): void {
    this.write('ERROR', msg, args);
  }

  private write(level: LogLevel, msg: string, args: unknown[]): void {
    if (LEVEL_RANK[level] < LEVEL_RANK[this.level]) return;
    const stamp = new Date().toISOString().replace('T', ' ').slice(0, 19);
    const prefix = `[${stamp}] [${level}]`;
    if (level === 'ERROR') console.error(prefix, msg, ...args);
    else if (level === 'WARN') console.warn(prefix, msg, ...args);
    else console.log(prefix, msg, ...args);
  }
}

export const logger = new Logger();

/** 每个用例跑之前生成唯一数据，避免残留数据互相影响 */
export class DataGenerator {
  private static suffix(): string {
    return Math.random().toString(36).slice(2, 6);
  }

  static username(): string {
    return `test_${this.suffix()}`;
  }

  static email(): string {
    return `test_${this.suffix()}@example.com`;
  }

  static productName(): string {
    return `测试商品_${this.suffix()}`;
  }

  static mobile(): string {
    return `1${Math.floor(Math.random() * 10)}${String(Math.floor(Math.random() * 1e10)).padStart(9, '0')}`;
  }
}

import type { Page } from '@playwright/test';
import { config, hasAccount, readEnv, type Role } from './config';

/**
 * 接口登录：比 UI 登录快一个数量级，也不会因为登录页改版而集体失败。
 * 靠环境变量开关，不写死在代码里：
 *
 *   LOGIN_API_PATH=/api/auth/login
 *   LOGIN_API_BODY={"username":"{{username}}","password":"{{password}}"}
 *   LOGIN_API_TOKEN_PATH=data.token     可选：token 在响应里的路径
 *   LOGIN_TOKEN_STORAGE_KEY=token       可选：前端存 token 的 localStorage key
 *
 * 不给 LOGIN_API_PATH 时返回 ok:false，setup 自动退回 UI 登录。
 */
export type ApiLoginResult = { ok: true } | { ok: false; reason: string };

function renderBody(template: string, username: string, password: string): string {
  return template
    .replace(/\{\{\s*username\s*\}\}/g, username)
    .replace(/\{\{\s*password\s*\}\}/g, password);
}

function pickPath(source: unknown, target: string): unknown {
  return target.split('.').reduce<unknown>((acc, key) => {
    if (acc && typeof acc === 'object') return (acc as Record<string, unknown>)[key];
    return undefined;
  }, source);
}

export async function tryApiLogin(page: Page, role: Role): Promise<ApiLoginResult> {
  const loginPath = readEnv('LOGIN_API_PATH');
  if (!loginPath) return { ok: false, reason: '未配置 LOGIN_API_PATH' };
  if (!hasAccount(role)) return { ok: false, reason: `未配置 ${role} 账号` };

  const account = config[role];
  const template = readEnv(
    'LOGIN_API_BODY',
    '{"username":"{{username}}","password":"{{password}}"}',
  );

  let payload: unknown;
  try {
    payload = JSON.parse(renderBody(template, account.username, account.password));
  } catch {
    return { ok: false, reason: 'LOGIN_API_BODY 不是合法 JSON' };
  }

  try {
    // page.request 与页面共享 cookie jar：接口种下的 cookie 会直接进 storageState
    const response = await page.request.post(loginPath, { data: payload });
    if (!response.ok()) return { ok: false, reason: `登录接口返回 ${response.status()}` };

    const tokenPath = readEnv('LOGIN_API_TOKEN_PATH');
    const storageKey = readEnv('LOGIN_TOKEN_STORAGE_KEY');
    if (tokenPath && storageKey) {
      const token = pickPath(await response.json(), tokenPath);
      if (!token) return { ok: false, reason: `响应里没有 ${tokenPath}` };
      // 先把页面开到同源，再写 localStorage，storageState 才带得走
      await page.goto('/');
      await page.evaluate((args) => window.localStorage.setItem(args.key, args.value), {
        key: storageKey,
        value: String(token),
      });
    }
    return { ok: true };
  } catch (error) {
    return { ok: false, reason: error instanceof Error ? error.message : String(error) };
  }
}

import { test as base, type APIRequestContext } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';

/** 用例结束前要清理的资源（接口造的数据、临时文件等） */
export type Cleanup = () => Promise<void>;

type Fixtures = {
  loginPage: LoginPage;
  /** 带 baseURL 的接口上下文：造数 / 清理 / 断言后端状态 */
  api: APIRequestContext;
  /** 注册清理动作，teardown 时按注册逆序执行 */
  trackCleanup: (fn: Cleanup) => void;
};

/**
 * 统一 fixture 入口：页面对象、接口上下文、数据清理都在这里，
 * 用例只 import 这一份 test / expect，避免多套扩展互相不认识。
 */
export const test = base.extend<Fixtures>({
  loginPage: async ({ page }, use) => {
    await use(new LoginPage(page));
  },
  api: async ({ request }, use) => {
    await use(request);
  },
  trackCleanup: async ({}, use) => {
    const tasks: Cleanup[] = [];
    await use((fn) => {
      tasks.push(fn);
    });
    // 逆序清理；单条失败只告警，不影响其它清理与最终结果
    for (const fn of tasks.reverse()) {
      try {
        await fn();
      } catch (error) {
        console.warn('[cleanup] 清理失败，已忽略：', error);
      }
    }
  },
});

export { expect } from '@playwright/test';

import { expect, test } from '../../fixtures/test';

/**
 * 框架自检：只确认配置 / 环境变量 / 浏览器 / BASE_URL 这一层通不通，不碰业务。
 * tests/ 下一旦出现别的用例，playwright.config.ts 会自动把这条排除（不跑、也不进报告）；
 * 需要再确认框架时跑 `pnpm run check:framework`。
 */
test('框架自检 | 打开首页 | 能拿到页面', { tag: ['@smoke'] }, async ({ page }) => {
  const response = await page.goto('/');
  expect(response?.ok() ?? true, '首页返回了非 2xx/3xx').toBeTruthy();
  await expect(page).toHaveTitle(/.+/);
  await expect(page.locator('body')).toBeVisible();
});

import js from '@eslint/js';
import tseslint from 'typescript-eslint';

export default tseslint.config(
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    rules: {
      '@typescript-eslint/no-explicit-any': 'off',
      '@typescript-eslint/no-unused-vars': ['warn', { argsIgnorePattern: '^_' }],
      // Playwright fixture 允许空对象解构（不需要任何 fixture 时）
      'no-empty-pattern': 'off',
    },
  },
  {
    ignores: ['node_modules/', 'reports/', 'test-results/', 'playwright-report/', '.auth/'],
