import { test as setup, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { config, hasAccount, type Role } from '../utils/config';
import { tryApiLogin } from '../utils/api-auth';

const TARGETS: Array<{ role: Role; file: string }> = [
  { role: 'admin', file: '.auth/admin.json' },
  { role: 'user', file: '.auth/user.json' },
];

for (const target of TARGETS) {
  setup(`登录并保存登录态-${target.role}`, async ({ page }) => {
    setup.skip(!hasAccount(target.role), `未配置 ${target.role} 账号，跳过登录态生成`);

    // 1) 优先接口登录：快、稳，不受登录页改版影响
    const api = await tryApiLogin(page, target.role);
    if (!api.ok) {
      // 2) 接口不可用时退回 UI 登录（刚接入的项目通常走这条）
      console.warn(`[setup] 接口登录不可用（${api.reason}），改用 UI 登录`);
      const loginPage = new LoginPage(page);
      await loginPage.open();
      await loginPage.login(config[target.role].username, config[target.role].password);
      await expect(page).not.toHaveURL(/\/login/);
    }

    // 登录「成功」不等于登录态可用：接口返回 200 但没种 cookie / token 时，
    // 存下来的是匿名状态，业务用例会静默以未登录身份运行。这里至少留一条告警。
    const state = await page.context().storageState();
    const hasState =
      state.cookies.length > 0 || state.origins.some((origin) => origin.localStorage.length > 0);
    if (!hasState) {
      console.warn(
        `[setup] ${target.role} 登录流程结束了但没有任何 cookie / localStorage，` +
          '保存的登录态是匿名的；请检查 LOGIN_API_PATH 或登录页的 data-testid',
      );
    }

    await page.context().storageState({ path: target.file });
  });
}

export default {
  extends: ['@commitlint/config-conventional'],
  rules: {
    'type-enum': [
      2,
      'always',
      ['feat', 'fix', 'docs', 'style', 'refactor', 'perf', 'test', 'chore', 'revert', 'build'],
    ],
    'subject-case': [0],
  },
};

pipeline {
  agent { docker { image 'mcr.microsoft.com/playwright:v1.49.0-jammy' } }

  options {
    timeout(time: 45, unit: 'MINUTES')
    buildDiscarder(logRotator(numToKeepStr: '30'))
  }

  parameters {
    choice(name: 'LEVEL', choices: ['smoke', 'regression', 'edge'], description: '执行级别')
    choice(name: 'TEST_ENV', choices: ['test', 'prod'], description: '目标环境')
  }

  environment {
    // 显式声明 CI：重试 / forbidOnly / blob 报告都按 CI 策略走
    CI                     = '1'
    PLAYWRIGHT_HTML_REPORT = 'reports/playwright-report'
    ENV                    = "${params.TEST_ENV}"
    BASE_URL               = credentials("${params.TEST_ENV}-base-url")
    ADMIN_USERNAME         = credentials("${params.TEST_ENV}-admin-username")
    ADMIN_PASSWORD         = credentials("${params.TEST_ENV}-admin-password")
    USER_USERNAME          = credentials("${params.TEST_ENV}-user-username")
    USER_PASSWORD          = credentials("${params.TEST_ENV}-user-password")
  }

  stages {
    stage('安装依赖') {
      steps {
        // 有 pnpm 用 pnpm，容器里没有就退回 npm
        sh 'sh scripts/ci.sh install'
      }
    }
    stage('类型检查') {
      steps { sh 'sh scripts/ci.sh run typecheck' }
    }
    stage('测试') {
      steps {
        // 用例失败也要继续合报告，先记失败再往下走
        catchError(buildResult: 'FAILURE', stageResult: 'FAILURE') {
          sh "sh scripts/ci.sh run test:${params.LEVEL}"
        }
      }
    }
    stage('合并报告') {
      steps {
        // CI 下只出 blob，这里合成一份 HTML 供归档
        sh 'npx playwright merge-reports --reporter=html reports/blob'
      }
    }
  }

  post {
    always {
      // docker agent 会把 workspace 挂进容器，报告就在宿主机上，直接归档
      archiveArtifacts artifacts: 'reports/playwright-report/**, reports/allure-results/**', allowEmptyArchive: true
    }
  }
}
